// src/components/Equipment.js
import React, { useState } from 'react';
import styled from 'styled-components';
import Modal from 'react-modal';

const EquipmentGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
`;

const EquipmentItem = styled.div`
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 10px;
  background-color: ${({ isSelected }) => (isSelected ? '#d1e7dd' : '#fff')};
  text-align: center;
  cursor: pointer;
  transition: box-shadow 0.3s ease;

  &:hover {
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
  }
`;

const EquipmentImage = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: 8px;
`;

// Custom modal styling
const customStyles = {
  content: {
    top: '50%',
    left: '50%',
    right: 'auto',
    bottom: 'auto',
    marginRight: '-50%',
    transform: 'translate(-50%, -50%)',
    padding: '30px',
    width: '50%',
    borderRadius: '10px',
    boxShadow: '0 10px 30px rgba(0, 0, 0, 0.2)',
    border: 'none',
  },
};

const ModalHeader = styled.h2`
  margin: 0;
  color: #333;
`;

const ModalCloseButton = styled.button`
  background-color: #f44336;
  color: white;
  border: none;
  padding: 10px;
  border-radius: 5px;
  cursor: pointer;
  float: right;

  &:hover {
    background-color: #d32f2f;
  }
`;

const Equipment = ({ equipment, handleSelect, selectedItems = [] }) => {
  const [modalItem, setModalItem] = useState(null);

  const openModal = (item) => setModalItem(item);
  const closeModal = () => setModalItem(null);

  const isSelected = (item) =>
    selectedItems.some((selected) => selected.id === item.id);

  return (
    <>
      <EquipmentGrid>
        {equipment.map((item) => (
          <EquipmentItem
            key={item.id}
            isSelected={isSelected(item)}
            onClick={() => openModal(item)}
          >
            <EquipmentImage src={item.Image_URL} alt={item.Name} />
            <h3>{item.Name}</h3>
            <p>Brand: {item.Brand}</p>
            <p>Price: ${item.Price}</p>
          </EquipmentItem>
        ))}
      </EquipmentGrid>

      {modalItem && (
        <Modal isOpen={!!modalItem} onRequestClose={closeModal} style={customStyles}>
          <ModalHeader>
            {modalItem.Name}
            <ModalCloseButton onClick={closeModal}>Close</ModalCloseButton>
          </ModalHeader>
          <p>Brand: {modalItem.Brand}</p>
          <p>Price: ${modalItem.Price}</p>

          {modalItem.Details && (
            <>
              <h4>Details</h4>
              <ul>
                {modalItem.Details.map((detail, index) => (
                  <li key={index}>{detail}</li>
                ))}
              </ul>
            </>
          )}

          {modalItem.Tech_Specs && (
            <>
              <h4>Tech Specs</h4>
              <ul>
                {Object.entries(modalItem.Tech_Specs).map(([key, value]) => (
                  <li key={key}>
                    <strong>{key}:</strong> {value}
                  </li>
                ))}
              </ul>
            </>
          )}

          <a href={modalItem.Link} target="_blank" rel="noopener noreferrer">
            View Product Page
          </a>
          <button onClick={() => handleSelect(modalItem)}>
            {isSelected(modalItem) ? 'Remove from Selection' : 'Add to Selection'}
          </button>
        </Modal>
      )}
    </>
  );
};

export default Equipment;
